export const BUILTIN_QUESTION_META: ReadonlyArray<Pick<QuizQuestion, 'id' | 'subject' | 'chapterId'>> = GROUPS.flatMap(([subject, chapterId, ids]) => ids.split(' ').map(id => ({ id, subject, ...(chapterId ? { chapterId } : {}) })));
